package remoteui

const pageHTML = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Remote hosts</title></head><body>
<style>body{font:1rem system-ui;margin:0}main{max-width:70rem;margin:auto;padding:1rem}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:24rem;overflow:auto}bdi,dd,li{overflow-wrap:anywhere}summary{cursor:pointer}summary:focus-visible{outline:3px solid #1646c4;outline-offset:3px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}button,input{font:inherit}button,a,input{margin:.3rem}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #1646c4;outline-offset:3px}</style><main><h1>Remote hosts</h1><p>Read-only preview. Identity changes disable access. Logs and inspection metadata may contain secrets.</p>
<p><a href="/remote">All hosts</a> · <a href="/remote/enrollment">Enroll or update a host</a></p>{{if .Error}}<p role="alert">{{.Error}}</p>{{end}}{{if .Notice}}<p role="status">{{.Notice}}</p>{{end}}
{{range .Hosts}}<section><h2>{{.Name}}</h2><p>Target state: {{.State}}</p><a href="/remote/inventory?host={{.ID | urlquery}}">Dill inventory</a></section>{{else}}{{if not .Host}}<p>No hosts available.</p>{{end}}{{end}}
{{if .Containers}}<section><h2>Dill-managed containers</h2><ul>{{range .Containers}}<li>{{.Stack}} / {{.Service}} — {{.Name}} ({{.State}}; {{.Image}}) <span class="sr-only">Full container ID: {{.ID}}</span><code aria-hidden="true" title="Full container ID: {{.ID}}">{{.IDPrefix}}</code> <a aria-label="Inspect {{.Name}}, full container ID {{.ID}}" href="/remote/inspect?host={{$.Host | urlquery}}&amp;container={{.ID | urlquery}}">Inspect</a></li>{{end}}</ul></section>{{else}}{{if and .Host (not .Inspection) (not .Error) (not .Notice)}}<p>No Dill-managed containers returned.</p>{{end}}{{end}}
{{with .Inspection}}<section><h2>Inspect <bdi>{{.Name}}</bdi></h2><p><bdi>{{.Stack}}</bdi> / <bdi>{{.Service}}</bdi></p>
<p>Inspection metadata, including commands, paths and health tests, may contain secrets. Logs and environment values may also contain secrets; do not share your screen.</p>
<dl><dt>Full container ID</dt><dd><bdi>{{.ID}}</bdi></dd><dt>Image</dt><dd><bdi>{{.Image}}</bdi></dd><dt>Image ID</dt><dd><bdi>{{.ImageID}}</bdi></dd><dt>State</dt><dd><bdi>{{.State}}</bdi></dd><dt>Created</dt><dd>{{with .CreatedAt}}<bdi>{{.}}</bdi>{{else}}Unavailable{{end}}</dd><dt>Observed</dt><dd><bdi>{{.ObservedAt}}</bdi></dd><dt>User</dt><dd>{{with .User}}<bdi>{{.}}</bdi>{{else}}Unavailable{{end}}</dd></dl>
<details><summary>Command and environment names</summary><h3>Command arguments</h3><ul>{{range .Command}}<li><bdi>{{.}}</bdi></li>{{else}}<li>None reported.</li>{{end}}</ul><h3>Environment names only</h3><ul>{{range .EnvKeys}}<li><bdi>{{.}}</bdi></li>{{else}}<li>No environment names.</li>{{end}}</ul></details>
<details><summary>Ports, mounts and networks</summary><h3>Ports</h3><ul>{{range .Ports}}<li><bdi>{{.HostIP}}</bdi>:{{.HostPort}} → {{.ContainerPort}} / <bdi>{{.Protocol}}</bdi></li>{{else}}<li>None reported.</li>{{end}}</ul><h3>Mounts</h3><ul>{{range .Mounts}}<li><bdi>{{.Type}}</bdi>: <bdi>{{.Source}}</bdi> → <bdi>{{.Destination}}</bdi> ({{if .ReadOnly}}read-only{{else}}read-write{{end}})</li>{{else}}<li>None reported.</li>{{end}}</ul><h3>Networks</h3><ul>{{range .Networks}}<li><bdi>{{.}}</bdi></li>{{else}}<li>None reported.</li>{{end}}</ul></details>
<details><summary>Restart and health</summary><dl><dt>Restart policy</dt><dd>{{with .RestartPolicy}}<bdi>{{.}}</bdi>{{else}}Unavailable{{end}}</dd><dt>Health status</dt><dd>{{with .Health.Status}}<bdi>{{.}}</bdi>{{else}}Unavailable{{end}}</dd></dl><h3>Health test arguments</h3><ul>{{range .Health.Test}}<li><bdi>{{.}}</bdi></li>{{else}}<li>None reported.</li>{{end}}</ul></details>
<details><summary>Resources and security</summary><dl><dt>Memory bytes</dt><dd>{{with .Resources.MemoryBytes}}{{.}}{{else}}Unavailable{{end}}</dd><dt>CPU nano</dt><dd>{{with .Resources.CPUNano}}{{.}}{{else}}Unavailable{{end}}</dd><dt>PID limit</dt><dd>{{with .Resources.PidsLimit}}{{.}}{{else}}Unavailable{{end}}</dd><dt>Privileged</dt><dd>{{with .Security.Privileged}}{{.}}{{else}}Unavailable{{end}}</dd><dt>Network mode</dt><dd>{{with .Security.NetworkMode}}<bdi>{{.}}</bdi>{{else}}Unavailable{{end}}</dd><dt>PID mode</dt><dd>{{with .Security.PIDMode}}<bdi>{{.}}</bdi>{{else}}Unavailable{{end}}</dd><dt>IPC mode</dt><dd>{{with .Security.IPCMode}}<bdi>{{.}}</bdi>{{else}}Unavailable{{end}}</dd></dl><h3>Added capabilities</h3><ul>{{range .Security.CapAdd}}<li><bdi>{{.}}</bdi></li>{{else}}<li>None reported.</li>{{end}}</ul></details>
<details><summary>Ownership labels</summary><dl>{{range $key, $value := .Labels}}<dt><bdi>{{$key}}</bdi></dt><dd><bdi>{{$value}}</bdi></dd>{{else}}<dt>Labels</dt><dd>None reported.</dd>{{end}}</dl></details>
<div id="reveal" data-csrf="{{$.CSRF}}" data-host="{{$.Host}}" data-container="{{$.Container}}"></div><pre id="values" hidden></pre><button type="button" id="clear" hidden>Clear values</button>
<div id="logs"><label><input type="checkbox" id="follow"> Follow live logs (up to five minutes)</label><button type="button" id="logs-button">Show last 100 log lines</button></div><button type="button" id="stop">Stop logs</button><pre id="log-output" aria-label="Container logs"></pre><p id="status" role="status"></p></section>{{end}}</main>
<script>
(()=>{
 const form=document.getElementById('reveal'); if(!form)return;
 const values=document.getElementById('values'), logs=document.getElementById('log-output'), status=document.getElementById('status');
 let timer, poll, controller, revealController, generation=0, displayUntil=0;
 function clear(){generation++;values.textContent='';clearTimeout(timer);clearTimeout(poll);if(revealController)revealController.abort()}
 async function session(){const started=performance.now();const r=await fetch('/remote/session',{cache:'no-store',redirect:'error',headers:{Accept:'application/json'}});if(!r.ok)throw Error();const d=await r.json();const ms=d.remainingMs-(performance.now()-started)-1000;if(!Number.isFinite(ms)||ms<=0)throw Error();return ms}
 async function monitor(g){try{const ms=await session();if(g!==generation)return;const remaining=Math.min(ms,displayUntil-performance.now());if(remaining<=0){clear();status.textContent='Values cleared';return}clearTimeout(timer);timer=setTimeout(()=>{clear();status.textContent='Session expired or display timed out; values cleared'},remaining);poll=setTimeout(()=>monitor(g),Math.min(remaining,2000))}catch(_){if(g===generation){clear();status.textContent='Session unavailable; values cleared'}}}
 document.getElementById('clear').onclick=clear;
 window.addEventListener('pagehide',()=>{clear();logs.textContent='';if(controller)controller.abort()});document.addEventListener('visibilitychange',()=>{if(document.hidden)clear()});

 document.getElementById('stop').onclick=()=>{if(controller)controller.abort()};
 document.getElementById('logs-button').addEventListener('click',async ()=>{if(controller)controller.abort();controller=new AbortController();logs.textContent='';status.textContent='Loading logs';try{const body=new URLSearchParams({_csrf:form.dataset.csrf,host:form.dataset.host,container:form.dataset.container});if(document.getElementById('follow').checked)body.set('follow','yes');const r=await fetch('/remote/logs',{method:'POST',body,cache:'no-store',redirect:'error',signal:controller.signal});if(!r.ok){clear();throw Error()}const reader=r.body.getReader(), decoder=new TextDecoder(), logDecoder=new TextDecoder();let buffer='',ended=false;while(true){const x=await reader.read();buffer+=decoder.decode(x.value||new Uint8Array(),{stream:!x.done});let i;while((i=buffer.indexOf('\n'))>=0){const line=buffer.slice(0,i);buffer=buffer.slice(i+1);const event=JSON.parse(line);if(ended)throw Error();if(event.type==='chunk'){const bytes=Uint8Array.from(atob(event.bytesBase64),c=>c.charCodeAt(0));logs.textContent+=logDecoder.decode(bytes,{stream:true})}else if(event.type==='end'){logs.textContent+=logDecoder.decode();ended=true;status.textContent='Log stream ended: '+event.reason}else if(event.type==='error'){ended=true;status.textContent='Log stream incomplete: '+event.reason}else if(event.type!=='heartbeat')throw Error()}if(x.done)break}if(!ended||buffer)status.textContent='Log stream incomplete: missing end'}catch(e){status.textContent=e.name==='AbortError'?'Logs stopped; stream incomplete':'Logs unavailable or incomplete'}})
})();
</script></body></html>`
